_SRC['autopost.config'] = 'import os\nfrom pathlib import Path\n\nimport yaml\n\nROOT = Path(__file__).resolve().parent\nCONFIG_DIR = ROOT\nDATA_DIR = ROOT\nHISTORY_FILE = DATA_DIR / "history.json"\n\nwith open(CONFIG_DIR / "settings.yaml", encoding="utf-8") as f:\n    S = yaml.safe_load(f)\n\nSTYLE = (CONFIG_DIR / "style.md").read_text(encoding="utf-8")\n\n\ndef env(name: str, required: bool = True) -> str:\n    val = os.environ.get(name, "").strip()\n    if required and not val:\n        raise RuntimeError(f"Secret topilmadi: {name}")\n    return val\n\n\nGEMINI_API_KEY = lambda: env("GEMINI_API_KEY")\nELEVENLABS_API_KEY = lambda: env("ELEVENLABS_API_KEY", required=False)\nBOT_TOKEN = lambda: env("TELEGRAM_BOT_TOKEN")\nADMIN_CHAT_ID = lambda: env("ADMIN_CHAT_ID")\nCHANNEL_ID = lambda: env("CHANNEL_ID")\n\n\ndef channel_at() -> str:\n    ch = os.environ.get("CHANNEL_ID", "").strip()\n    return ch if ch.startswith("@") else "@vibecodingkurs"\n\n\nif not S.get("channel_signature"):\n    S["channel_signature"] = channel_at()\nSTYLE = STYLE.replace("@vibecodingkurs", channel_at())\n'


