_SRC['autopost.llm'] = '"""Gemini bilan ishlash: matn, qidiruv, rasm, ovoz.\nAvval yangi Interactions API, ishlamasa eski generate_content. Model ishlamasa keyingisiga o\'tadi."""\nimport base64\nimport json\nimport logging\nimport re\nimport time\n\nfrom google import genai\nfrom google.genai import types\n\nfrom . import config\n\nlog = logging.getLogger("llm")\n_client = None\n\n\ndef client():\n    global _client\n    if _client is None:\n        key = config.GEMINI_API_KEY()\n        vertex = config.env("GEMINI_VERTEX", required=False) == "1"\n        log.info("Gemini rejimi: %s", "Vertex AI" if vertex else "AI Studio")\n        _client = genai.Client(vertexai=True, api_key=key) if vertex else genai.Client(api_key=key)\n    return _client\n\n\ndef _fatal(e) -> bool:\n    s = str(e)\n    return any(c in s for c in ("API_KEY_INVALID", "API key not valid", "401 ", "UNAUTHENTICATED"))\n\n\ndef _transient(e) -> bool:\n    s = str(e)\n    if "exceeded your current quota" in s or "limit: 0" in s:\n        return False  # kvota tugagan — kutish foyda bermaydi, keyingi modelga o\'tamiz\n    return any(c in s for c in ("429", "500", "502", "503", "504", "RESOURCE_EXHAUSTED", "UNAVAILABLE",\n                                "timed out", "Timeout", "Connection"))\n\n\nEXTRA = {\n    "text_models": ["gemini-3.8-flash", "gemini-3.7-flash", "gemini-3.5-flash", "gemini-3.5-flash-lite",\n                    "gemini-3.1-flash-lite"],\n    "image_models": ["gemini-3.1-flash-image", "gemini-3.1-flash-lite-image", "gemini-3-pro-image"],\n    "tts_models": ["gemini-3.8-flash-tts", "gemini-3.8-flash-lite-tts", "gemini-3.1-flash-tts-preview"],\n}\n\n\ndef _models(kind):\n    out = []\n    for m in list(config.S.get(kind, [])) + EXTRA[kind]:\n        if m not in out and not m.startswith("gemini-2."):\n            out.append(m)\n    return out\n\n\ndef _try_models(models, fn):\n    """fn(model) ni har bir model uchun sinaydi. Hamma xatolarni yig\'adi."""\n    errors = []\n    for model in models:\n        for attempt in range(3):\n            try:\n                return fn(model)\n            except Exception as e:  # noqa: BLE001\n                msg = f"{model}: {str(e)[:220]}"\n                if _fatal(e):\n                    raise RuntimeError("Gemini kaliti/ruxsat xatosi: " + msg) from e\n                if _transient(e) and attempt < 2:\n                    wait = 10 * (attempt + 1)\n                    log.warning("%s — %ss kutib qayta urinamiz", msg, wait)\n                    time.sleep(wait)\n                    continue\n                log.warning("Ishlamadi: %s", msg)\n                errors.append(msg)\n                break\n    raise RuntimeError("Gemini javob bermadi:\\n" + "\\n".join(errors[-6:]))\n\n\ndef _b64(data) -> bytes:\n    if isinstance(data, (bytes, bytearray)):\n        return bytes(data)\n    return base64.b64decode(data)\n\n\n# ---------------- Interactions API ----------------\ndef _ia_text(model, prompt, system, search, images):\n    if images:\n        inp = [{"type": "text", "text": prompt}] + [\n            {"type": "image", "data": base64.b64encode(i).decode(), "mime_type": "image/png"} for i in images]\n    else:\n        inp = prompt\n    kw = {"model": model, "input": inp}\n    if system:\n        kw["system_instruction"] = system\n    if search:\n        kw["tools"] = [{"type": "google_search"}]\n    r = client().interactions.create(**kw)\n    t = getattr(r, "output_text", None)\n    if not t:\n        raise RuntimeError("bo\'sh javob")\n    return t\n\n\ndef _gc_text(model, prompt, system, search, images, temperature, json_out):\n    tools = [types.Tool(google_search=types.GoogleSearch())] if search else None\n    cfg = types.GenerateContentConfig(\n        system_instruction=system, temperature=temperature, tools=tools,\n        response_mime_type="application/json" if (json_out and not search) else None)\n    contents = [prompt] + [types.Part.from_bytes(data=i, mime_type="image/png") for i in images or []]\n    r = client().models.generate_content(model=model, contents=contents, config=cfg)\n    if not r.text:\n        raise RuntimeError("bo\'sh javob")\n    return r.text\n\n\ndef text(prompt, system=None, search=False, temperature=0.8, json_out=False, images=None) -> str:\n    if json_out:\n        prompt += "\\n\\nJavobni FAQAT to\'g\'ri JSON ko\'rinishida ber, boshqa hech narsa yozma."\n\n    def fn(model):\n        try:\n            return _ia_text(model, prompt, system, search, images)\n        except Exception as e1:  # noqa: BLE001\n            if _fatal(e1):\n                raise\n            log.info("Interactions API (%s) ishlamadi, generate_content sinaymiz: %s", model, str(e1)[:150])\n            try:\n                return _gc_text(model, prompt, system, search, images, temperature, json_out)\n            except Exception as e2:  # noqa: BLE001\n                if search:  # qidiruvsiz oxirgi urinish\n                    try:\n                        return _gc_text(model, prompt, system, False, images, temperature, json_out)\n                    except Exception:  # noqa: BLE001\n                        pass\n                raise RuntimeError(f"IA: {str(e1)[:150]} | GC: {str(e2)[:150]}") from e2\n\n    return _try_models(_models("text_models"), fn)\n\n\ndef jtext(prompt, **kw):\n    """JSON qaytaradigan chaqiruv. Buzuq JSON bo\'lsa, bir marta tuzattiradi."""\n    raw = text(prompt, json_out=True, **kw)\n    try:\n        return parse_json(raw)\n    except ValueError:\n        fixed = text("Quyidagini faqat to\'g\'ri JSON ko\'rinishida qaytar, boshqa hech narsa yozma:\\n\\n" + raw,\n                     json_out=True, temperature=0)\n        return parse_json(fixed)\n\n\ndef parse_json(raw: str):\n    raw = raw.strip()\n    raw = re.sub(r"^```(?:json)?\\s*|\\s*```$", "", raw)\n    try:\n        return json.loads(raw)\n    except json.JSONDecodeError:\n        m = re.search(r"(\\{.*\\}|\\[.*\\])", raw, re.S)\n        if m:\n            return json.loads(m.group(1))\n    raise ValueError("JSON topilmadi")\n\n\n# ---------------- Rasm ----------------\ndef image(prompt: str) -> bytes:\n    ar = config.S["image_aspect_ratio"]\n\n    def fn(model):\n        try:\n            r = client().interactions.create(model=model, input=prompt,\n                                             response_format={"type": "image", "aspect_ratio": ar})\n            img = getattr(r, "output_image", None)\n            if img is not None and getattr(img, "data", None):\n                return _b64(img.data)\n            raise RuntimeError("rasm qaytmadi")\n        except Exception as e1:  # noqa: BLE001\n            if _fatal(e1):\n                raise\n            cfg = types.GenerateContentConfig(response_modalities=["IMAGE"],\n                                              image_config=types.ImageConfig(aspect_ratio=ar))\n            try:\n                r = client().models.generate_content(model=model, contents=[prompt], config=cfg)\n            except Exception as e2:  # noqa: BLE001\n                raise RuntimeError(f"IA: {str(e1)[:150]} | GC: {str(e2)[:150]}") from e2\n            for cand in r.candidates or []:\n                for part in (cand.content.parts if cand.content else []) or []:\n                    if part.inline_data and part.inline_data.data:\n                        return part.inline_data.data\n            raise RuntimeError("rasm qaytmadi") from e1\n\n    return _try_models(_models("image_models"), fn)\n\n\n# ---------------- Ovoz ----------------\ndef tts(prompt: str, voice: str) -> bytes:\n    """Audio baytlarini qaytaradi (WAV yoki xom PCM 24kHz)."""\n\n    def fn(model):\n        try:\n            r = client().interactions.create(\n                model=model, input=prompt, response_format={"type": "audio"},\n                generation_config={"speech_config": [{"voice": voice}]})\n            a = getattr(r, "output_audio", None)\n            if a is not None and getattr(a, "data", None):\n                return _b64(a.data)\n            raise RuntimeError("audio qaytmadi")\n        except Exception as e1:  # noqa: BLE001\n            if _fatal(e1):\n                raise\n            cfg = types.GenerateContentConfig(\n                response_modalities=["AUDIO"],\n                speech_config=types.SpeechConfig(voice_config=types.VoiceConfig(\n                    prebuilt_voice_config=types.PrebuiltVoiceConfig(voice_name=voice))))\n            try:\n                r = client().models.generate_content(model=model, contents=[prompt], config=cfg)\n            except Exception as e2:  # noqa: BLE001\n                raise RuntimeError(f"IA: {str(e1)[:150]} | GC: {str(e2)[:150]}") from e2\n            for cand in r.candidates or []:\n                for part in (cand.content.parts if cand.content else []) or []:\n                    if part.inline_data and part.inline_data.data:\n                        return part.inline_data.data\n            raise RuntimeError("audio qaytmadi") from e1\n\n    return _try_models(_models("tts_models"), fn)\n'


