_SRC['autopost.telegram'] = '"""Telegram Bot API — faqat kerakli metodlar."""\nimport json\nimport logging\n\nimport requests\n\nfrom . import config\n\nlog = logging.getLogger("tg")\n\n\ndef _api(method, data=None, files=None, timeout=60):\n    url = f"https://api.telegram.org/bot{config.BOT_TOKEN()}/{method}"\n    r = requests.post(url, data=data, files=files, timeout=timeout)\n    res = r.json()\n    if not res.get("ok"):\n        raise RuntimeError(f"Telegram {method}: {res.get(\'description\')}")\n    return res["result"]\n\n\ndef send_message(chat_id, text, markup=None, html=True):\n    data = {"chat_id": chat_id, "text": text, "disable_web_page_preview": "true"}\n    if html:\n        data["parse_mode"] = "HTML"\n    if markup:\n        data["reply_markup"] = json.dumps(markup)\n    return _api("sendMessage", data)\n\n\ndef send_photo(chat_id, photo: bytes, caption: str):\n    data = {"chat_id": chat_id, "caption": caption, "parse_mode": "HTML"}\n    return _api("sendPhoto", data, files={"photo": ("post.png", photo, "image/png")})\n\n\ndef send_voice(chat_id, ogg: bytes | None, mp3: bytes | None, caption=""):\n    if ogg:\n        try:\n            return _api("sendVoice", {"chat_id": chat_id, "caption": caption, "parse_mode": "HTML"},\n                        files={"voice": ("maslahat.ogg", ogg, "audio/ogg")})\n        except Exception as e:  # noqa: BLE001\n            log.warning("sendVoice ishlamadi, audio sifatida yuboramiz: %s", e)\n    if mp3:\n        return _api("sendAudio", {"chat_id": chat_id, "caption": caption, "parse_mode": "HTML",\n                                  "title": "Claude maslahat", "performer": "vibecodingkurs"},\n                    files={"audio": ("maslahat.mp3", mp3, "audio/mpeg")})\n\n\ndef edit_text(chat_id, message_id, text):\n    try:\n        _api("editMessageText", {"chat_id": chat_id, "message_id": message_id, "text": text,\n                                 "parse_mode": "HTML"})\n    except Exception as e:  # noqa: BLE001\n        log.warning("edit xato: %s", e)\n\n\ndef answer_callback(cq_id, text=""):\n    try:\n        _api("answerCallbackQuery", {"callback_query_id": cq_id, "text": text})\n    except Exception as e:  # noqa: BLE001\n        log.warning("answerCallback xato: %s", e)\n\n\ndef get_updates(offset=None, timeout=20):\n    data = {"timeout": timeout, "allowed_updates": json.dumps(["callback_query"])}\n    if offset is not None:\n        data["offset"] = offset\n    return _api("getUpdates", data, timeout=timeout + 15)\n\n\ndef drain_updates():\n    """Eski bosilgan tugmalarni o\'tkazib yuborish; keyingi offset\'ni qaytaradi."""\n    ups = get_updates(offset=-1, timeout=0)\n    if ups:\n        nxt = ups[-1]["update_id"] + 1\n        get_updates(offset=nxt, timeout=0)\n        return nxt\n    return None\n\n\ndef publish(chat_id, post):\n    """Rasm+matn, keyin ovoz. Rasm bo\'lmasa — matn."""\n    if post.get("image"):\n        msg = send_photo(chat_id, post["image"], post["caption"])\n    else:\n        msg = send_message(chat_id, post["caption"])\n    if post.get("voice_ogg") or post.get("voice_mp3"):\n        try:\n            send_voice(chat_id, post.get("voice_ogg"), post.get("voice_mp3"),\n                       caption="🎧 Maslahatni tinglang")\n        except Exception as e:  # noqa: BLE001\n            log.warning("Audio yuborilmadi: %s", e)\n    return msg\n'


