_SRC['autopost.agents.writer'] = '"""2-agent: mavzu bo\'yicha maslahatni aniqlashtiradi va uslubda post yozadi."""\nimport logging\nimport re\n\nfrom .. import config, llm\n\nlog = logging.getLogger("agent2.writer")\n\nSYSTEM = ("Sen qisqa, o\'ychan, aforizmli uslubda yozadigan o\'zbek muallifisan va Claude bo\'yicha ekspertsan. "\n          "Faktlarni internetdan tekshirasan, hech narsani uydirmaysan. Faqat o\'zbek lotin yozuvida yozasan.")\n\nALLOWED_TAGS = ("b", "i", "code", "blockquote")\n\n\ndef visible_len(html: str) -> int:\n    t = re.sub(r"<[^>]+>", "", html)\n    t = t.replace("&lt;", "<").replace("&gt;", ">").replace("&amp;", "&")\n    return len(t)\n\n\ndef sanitize(html: str) -> str:\n    def keep(m):\n        tag = m.group(2).lower()\n        return m.group(0) if tag in ALLOWED_TAGS else ""\n    html = re.sub(r"<(/?)([a-zA-Z0-9]+)[^>]*>", keep, html)\n    html = re.sub(r"<(b|i|code|blockquote)\\s[^>]*>", r"<\\1>", html)\n    html = re.sub(r"&(?!(lt|gt|amp|quot);)", "&amp;", html)\n    return re.sub(r"\\n{3,}", "\\n\\n", html).strip()\n\n\ndef write(topic: dict, feedback: str | None = None, previous: dict | None = None) -> dict:\n    max_chars = config.S["caption_max_chars"]\n    fix = ""\n    if feedback and previous:\n        fix = f"""\nOLDINGI VARIANT sifat nazoratidan o\'tmadi. Kamchiliklar:\n{feedback}\n\nOldingi matn:\n{previous.get(\'caption\')}\n\nShu kamchiliklarni to\'liq tuzatib, qaytadan yoz."""\n\n    prompt = f"""Rubrika: {config.S[\'rubric\']}\nMavzu: {topic.get(\'topic\')}\nNimasi foydali: {topic.get(\'angle\')}\nTadqiqotchi topgan faktlar: {topic.get(\'key_facts\')}\nManba: {topic.get(\'source_url\')}\n\n1) Avval internetdan shu maslahatni tekshir: qadamlar va funksiya nomlari hozir ham to\'g\'rimi.\n2) Keyin quyidagi USLUB bo\'yicha Telegram post yoz.\n\nUSLUB:\n{config.STYLE}\n\nEng oxirgi qatorda faqat: {config.S[\'channel_signature\']}{(\' \' + config.S[\'rubric_hashtag\']) if config.S.get(\'rubric_hashtag\') else \'\'}\nKo\'rinadigan matn {max_chars} belgidan OSHMASIN.\n{fix}\n\nJavob faqat JSON:\n{{"title": "qisqa sarlavha (history uchun)",\n  "headline": "rasm ustiga yoziladigan 2-5 so\'zlik tezis (postning birinchi qatoriga yaqin)",\n  "caption": "Telegram HTML post",\n  "audio_script": "ovoz uchun matn: 40-70 soniya (90-150 so\'z), tabiiy og\'zaki o\'zbek tilida, emoji/teg/havola/heshteg YO\'Q. Inglizcha so\'zlarni o\'zbekcha talaffuzda yoz: Claude -> Klod, prompt -> prompt, Projects -> Proyekts. postdagi kabi sokin, o\'ychan ohangda, qisqa gaplar bilan; postning o\'zini o\'qib bermasin, og\'zaki qilib aytsin; oxirida bir gap bilan {config.channel_at().lstrip(\'@\')} kanalini eslatsin",\n  "image_idea": "rasm uchun vizual g\'oya, 1-2 gap, ingliz tilida",\n  "sources": ["havola"]}}"""\n    raw = llm.text(prompt, system=SYSTEM, search=True, temperature=0.7)\n    try:\n        post = llm.parse_json(raw)\n    except ValueError:\n        post = llm.jtext("Quyidagini ko\'rsatilgan kalitlar bilan JSON ob\'ektga o\'tkaz "\n                         "(title, headline, caption, audio_script, image_idea, sources):\\n" + raw)\n    post["caption"] = sanitize(post.get("caption", ""))\n    if visible_len(post["caption"]) > 1024:\n        post["caption"] = shorten(post["caption"], max_chars)\n    post["topic"] = topic.get("topic")\n    return post\n\n\ndef shorten(caption: str, max_chars: int) -> str:\n    log.info("Matn uzun (%s), qisqartiramiz", visible_len(caption))\n    for _ in range(2):\n        caption = sanitize(llm.text(\n            f"Quyidagi Telegram HTML postni ma\'nosini, formatini va teglarni saqlab, ko\'rinadigan matnni "\n            f"{max_chars - 100} belgigacha qisqartir. Faqat postning o\'zini qaytar:\\n\\n{caption}",\n            temperature=0.3))\n        if visible_len(caption) <= 1024:\n            break\n    return caption\n'


