_SRC['autopost.agents.topic'] = '"""1-agent: rubrika bo\'yicha internetdan yangi mavzular topadi."""\nimport logging\n\nfrom .. import config, llm\n\nlog = logging.getLogger("agent1.topic")\n\nSYSTEM = ("Sen Telegram kanal uchun kontent-tadqiqotchisan. Internetdan (rasmiy hujjatlar, "\n          "Anthropic blogi, docs.claude.com, support.claude.com, tajribali foydalanuvchilar maqolalari, "\n          "Reddit, X) eng foydali va dolzarb amaliy maslahatlarni topasan. Faqat haqiqiy, tekshirilgan "\n          "funksiyalar haqida yoz.")\n\n\ndef find_topics(past_titles: list[str], exclude: list[str] | None = None, n: int = 6) -> list[dict]:\n    rubric = config.S["rubric"]\n    avoid = "\\n".join(f"- {t}" for t in (past_titles[-80:] + (exclude or []))) or "- (hali yo\'q)"\n    prompt = f"""Rubrika: "{rubric}".\n\nInternetdan qidirib, shu rubrikaga mos {n} ta YANGI, amaliy maslahat mavzusini top.\nTalablar:\n- Har biri bitta aniq, darhol qo\'llasa bo\'ladigan maslahat (umumiy gap emas).\n- Oddiy foydalanuvchi uchun foydali: Claude.ai chat, Projects, Artifacts, Skills, prompt yozish,\n  fayllar bilan ishlash, Claude Code, integratsiyalar va h.k.\n- Iloji boricha so\'nggi oylardagi yangiliklar yoki kam ma\'lum usullar.\n- Quyidagi avval chiqqan mavzularni TAKRORLAMA:\n{avoid}\n\nJavobni faqat JSON massiv ko\'rinishida ber:\n[{{"topic": "mavzu (o\'zbekcha, qisqa)", "angle": "nimasi foydali, 1 gap",\n   "key_facts": "manbadagi aniq faktlar, qadamlar", "source_url": "manba havolasi",\n   "freshness": 1-10, "usefulness": 1-10}}]"""\n    raw = llm.text(prompt, system=SYSTEM, search=True, temperature=0.9)\n    try:\n        items = llm.parse_json(raw)\n    except ValueError:\n        items = llm.jtext("Quyidagi matndan mavzular ro\'yxatini yuqoridagi JSON massiv formatiga o\'tkaz:\\n" + raw)\n    if isinstance(items, dict):\n        items = items.get("topics") or list(items.values())[0]\n    items = [i for i in items if isinstance(i, dict) and i.get("topic")]\n    items.sort(key=lambda i: (int(i.get("usefulness", 0) or 0) * 2 + int(i.get("freshness", 0) or 0)),\n               reverse=True)\n    log.info("Topilgan mavzular: %s", [i["topic"] for i in items])\n    if not items:\n        raise RuntimeError("Mavzu topilmadi")\n    return items\n'


