# autopost.agents.image
# ======================================================================
_SRC['autopost.agents.image'] = '"""3-agent: Nano Banana orqali post rasmi; matni buzilgan bo\'lsa qayta chizadi."""\nimport logging\n\nfrom .. import llm\n\nlog = logging.getLogger("agent3.image")\n\nBRAND = ("Minimal, calm, thoughtful editorial poster. Warm off-white paper background (#F4EFE6) with subtle "\n         "paper grain. One simple metaphorical object drawn in fine black ink line-art with a single terracotta "\n         "accent (#C8553D) — e.g. a cup, a key, a lamp, a notebook, a compass, a chat bubble. "\n         "Huge negative space, quiet and elegant, like a page from a philosophy book. "\n         "No logos, no brand marks, no real people, no watermark, no gradients, no neon.")\n\n\ndef make_prompt(post: dict) -> str:\n    return (f"{BRAND}\\n\\nScene: {post.get(\'image_idea\')}\\n\\n"\n            f"Place one bold, large, perfectly spelled headline at the top in Uzbek Latin script, exactly: "\n            f"\\"{post.get(\'headline\')}\\". Use an elegant black serif font, lowercase, max 2 lines. "\n            f"No other text in the image. Vertical 4:5 composition.")\n\n\ndef check(img: bytes, headline: str) -> tuple[bool, str]:\n    res = llm.jtext(\n        f"Rasmni tekshir. Unda faqat shu sarlavha bo\'lishi kerak: \\"{headline}\\". "\n        f"Harflar to\'g\'ri va o\'qiladigan, ortiqcha/buzilgan yozuv yo\'q, logotip yo\'q, sifatli ko\'rinadimi? "\n        f\'JSON: {{"ok": true/false, "issue": "muammo bo\\\'lsa qisqa"}}\',\n        images=[img], temperature=0)\n    return bool(res.get("ok")), res.get("issue", "")\n\n\ndef generate(post: dict, tries: int = 3) -> bytes | None:\n    prompt = make_prompt(post)\n    best = None\n    for i in range(tries):\n        try:\n            img = llm.image(prompt)\n        except Exception as e:  # noqa: BLE001\n            log.warning("Rasm yaratilmadi (%s): %s", i + 1, e)\n            continue\n        best = best or img\n        try:\n            ok, issue = check(img, post.get("headline", ""))\n        except Exception as e:  # noqa: BLE001\n            log.warning("Rasm tekshiruvi xato: %s", e)\n            return img\n        if ok:\n            return img\n        log.info("Rasm qayta chiziladi: %s", issue)\n        best = img\n        prompt += f"\\nIMPORTANT: previous attempt had this problem: {issue}. Fix it."\n    return best\n'


# ======================================================================
# autopost.agents.audio
# ======================================================================
_SRC['autopost.agents.audio'] = '"""4-agent: maslahatni ovozga aylantiradi.\nAsosiy: Gemini TTS (o\'zbek tilini qo\'llaydi). Zaxira: ElevenLabs (kalit bo\'lsa).\nNatija: Telegram voice uchun OGG/Opus + MP3."""\nimport logging\nimport subprocess\nimport tempfile\nfrom pathlib import Path\n\nimport requests\n\nfrom .. import config, llm\n\nlog = logging.getLogger("agent4.audio")\n\n\ndef _ffmpeg(src_bytes: bytes, in_args: list[str], out_ext: str, out_args: list[str]) -> bytes:\n    with tempfile.TemporaryDirectory() as d:\n        src, dst = Path(d) / "in.bin", Path(d) / f"out.{out_ext}"\n        src.write_bytes(src_bytes)\n        subprocess.run(["ffmpeg", "-y", "-loglevel", "error", *in_args, "-i", str(src), *out_args, str(dst)],\n                       check=True, timeout=120)\n        return dst.read_bytes()\n\n\ndef gemini_tts(text: str) -> bytes:\n    """Gemini TTS -> MP3."""\n    style = config.S.get("tts_style", "")\n    prompt = f"{style}\\n\\n{text}" if style else text\n    data = llm.tts(prompt, config.S["gemini_voice"])\n    in_args = [] if data[:4] == b"RIFF" else ["-f", "s16le", "-ar", "24000", "-ac", "1"]\n    return _ffmpeg(data, in_args, "mp3", ["-c:a", "libmp3lame", "-b:a", "128k"])\n\n\ndef eleven_tts(text: str) -> bytes:\n    key = config.ELEVENLABS_API_KEY()\n    if not key:\n        raise RuntimeError("ELEVENLABS_API_KEY yo\'q")\n    url = f"https://api.elevenlabs.io/v1/text-to-speech/{config.S[\'voice_id\']}?output_format=mp3_44100_128"\n    r = requests.post(url, headers={"xi-api-key": key, "Content-Type": "application/json"},\n                      json={"text": text, "model_id": config.S["tts_model"]}, timeout=180)\n    if r.ok and r.content:\n        return r.content\n    raise RuntimeError(f"ElevenLabs: {r.status_code} {r.text[:200]}")\n\n\ndef to_ogg(mp3: bytes) -> bytes | None:\n    try:\n        return _ffmpeg(mp3, [], "ogg", ["-c:a", "libopus", "-b:a", "64k", "-ac", "1"])\n    except Exception as e:  # noqa: BLE001\n        log.warning("OGG ga aylantirilmadi: %s", e)\n        return None\n\n\ndef generate(post: dict) -> tuple[bytes | None, bytes | None]:\n    text = post["audio_script"][:3000]\n    order = ["gemini", "elevenlabs"] if config.S.get("audio_provider", "gemini") == "gemini" \\\n        else ["elevenlabs", "gemini"]\n    errors = []\n    for prov in order:\n        try:\n            mp3 = gemini_tts(text) if prov == "gemini" else eleven_tts(text)\n            log.info("Audio tayyor: %s", prov)\n            return to_ogg(mp3), mp3\n        except Exception as e:  # noqa: BLE001\n            log.warning("%s audio xato: %s", prov, e)\n            errors.append(f"{prov}: {str(e)[:120]}")\n    raise RuntimeError("; ".join(errors))\n'


