_SRC['autopost.agents.qc'] = '"""5-agent: sifat nazorati."""\nimport logging\n\nfrom .. import config, llm\nfrom .writer import visible_len\n\nlog = logging.getLogger("agent5.qc")\n\nSYSTEM = ("Sen qattiqqo\'l bosh muharrir va Claude bo\'yicha faktchekersan. Postni kanalga chiqishdan oldin "\n          "tekshirasan. Faktlarni internetdan tekshir. Xushomad qilma.")\n\n\ndef review(post: dict) -> dict:\n    n = visible_len(post.get("caption", ""))\n    prompt = f"""Quyidagi Telegram postni tekshir.\n\nUSLUB QOIDALARI:\n{config.STYLE}\n\nPOST (Telegram HTML):\n{post.get(\'caption\')}\n\nAUDIO MATNI:\n{post.get(\'audio_script\')}\n\nKo\'rinadigan matn uzunligi: {n} belgi (chegara {config.S[\'caption_max_chars\']}).\n\nTekshir:\n1. Faktlar to\'g\'rimi? Funksiya nomlari, qadamlar hozirgi Claude\'da haqiqatan bormi (internetdan tekshir).\n2. O\'zbek lotin imlosi va grammatikasi to\'g\'rimi, tabiiy o\'qiladimi.\n3. Uslub va format qoidalariga mosmi (hook, qadamlar, misol, natija, imzo, heshteg).\n4. Foydalimi — o\'quvchi darhol qo\'llay oladimi.\n5. Audio matnda emoji/havola yo\'qmi, og\'zaki tabiiymi.\n\nJavob faqat JSON:\n{{"score": 1-10, "pass": true/false, "issues": ["aniq kamchilik va qanday tuzatish"]}}\npass=true faqat score >= {config.S[\'qc_min_score\']} va faktik xato bo\'lmasa."""\n    raw = llm.text(prompt, system=SYSTEM, search=True, temperature=0.1)\n    try:\n        res = llm.parse_json(raw)\n    except ValueError:\n        res = llm.jtext(\'Quyidagi baholashni {"score":int,"pass":bool,"issues":[str]} JSON ga o\\\'tkaz:\\n\' + raw)\n    res["score"] = int(res.get("score", 0) or 0)\n    if n > 1024:\n        res["pass"] = False\n        res.setdefault("issues", []).append(f"Matn {n} belgi — 1000 dan qisqa qil")\n    res["pass"] = bool(res.get("pass")) and res["score"] >= config.S["qc_min_score"]\n    log.info("QC: %s/10 pass=%s issues=%s", res["score"], res["pass"], res.get("issues"))\n    return res\n'


