# autopost.pipeline
# ======================================================================
_SRC['autopost.pipeline'] = '"""Agentlarni ketma-ket ishlatib, tayyor post yig\'adi."""\nimport logging\nfrom concurrent.futures import ThreadPoolExecutor\n\nfrom . import config\nfrom .agents import audio, image, qc, topic, writer\n\nlog = logging.getLogger("pipeline")\n\n\ndef _write_with_qc(t: dict) -> dict:\n    best, feedback, prev = None, None, None\n    for attempt in range(config.S["max_rewrites"] + 1):\n        post = writer.write(t, feedback=feedback, previous=prev)\n        res = qc.review(post)\n        post["qc"] = res\n        if best is None or res["score"] > best["qc"]["score"]:\n            best = post\n        if res["pass"]:\n            return post\n        feedback = "\\n".join(f"- {i}" for i in res.get("issues", []))\n        prev = post\n        log.info("Qayta yozish %s", attempt + 1)\n    return best\n\n\ndef build_post(past_titles: list[str], exclude: list[str] | None = None) -> dict:\n    topics = topic.find_topics(past_titles, exclude)          # 1-agent\n    post = None\n    for t in topics[:2]:\n        cand = _write_with_qc(t)                              # 2 + 5-agent\n        if post is None or cand["qc"]["score"] > post["qc"]["score"]:\n            post = cand\n        if cand["qc"]["pass"]:\n            break\n\n    warnings = []\n    if not post["qc"]["pass"]:\n        warnings.append(f"⚠️ Sifat nazorati: {post[\'qc\'][\'score\']}/10 — " +\n                        "; ".join(post["qc"].get("issues", [])[:3]))\n\n    with ThreadPoolExecutor(2) as ex:                         # 3 va 4-agent parallel\n        f_img = ex.submit(image.generate, post)\n        f_aud = ex.submit(audio.generate, post)\n        try:\n            post["image"] = f_img.result()\n        except Exception as e:  # noqa: BLE001\n            post["image"] = None\n            log.error("Rasm: %s", e)\n        if not post["image"]:\n            warnings.append("⚠️ Rasm yaratilmadi — post rasmsiz chiqadi")\n        try:\n            post["voice_ogg"], post["voice_mp3"] = f_aud.result()\n        except Exception as e:  # noqa: BLE001\n            post["voice_ogg"] = post["voice_mp3"] = None\n            log.error("Audio: %s", e)\n            warnings.append(f"⚠️ Audio yaratilmadi: {str(e)[:150]}")\n\n    post["warnings"] = warnings\n    return post\n'


