_SRC['autopost.main'] = '"""\n6-agent (nashrchi) + boshqaruv.\n\nRejimlar:\n  scheduled — 19:35 da sizga ko\'rsatadi, 19:45 da kanalga chiqaradi\n  now       — hozir tayyorlaydi, darhol ko\'rsatadi, 10 daqiqadan keyin chiqaradi\n  dry       — faqat sizga ko\'rsatadi, kanalga chiqarmaydi (sinov uchun)\n"""\nimport argparse\nimport html\nimport json\nimport logging\nimport time\nimport uuid\nfrom datetime import datetime, timedelta\nfrom zoneinfo import ZoneInfo\n\nfrom . import config, telegram as tg\nfrom .pipeline import build_post\n\nlogging.basicConfig(level=logging.INFO, format="%(asctime)s %(name)s: %(message)s")\nlog = logging.getLogger("main")\nTZ = ZoneInfo(config.S["timezone"])\n\n\ndef now():\n    return datetime.now(TZ)\n\n\ndef load_history():\n    try:\n        return json.loads(config.HISTORY_FILE.read_text(encoding="utf-8"))\n    except Exception:  # noqa: BLE001\n        return []\n\n\ndef save_history(h):\n    config.HISTORY_FILE.write_text(json.dumps(h, ensure_ascii=False, indent=2), encoding="utf-8")\n\n\ndef sleep_until(t):\n    while (left := (t - now()).total_seconds()) > 0:\n        time.sleep(min(left, 30))\n\n\ndef post_link(msg):\n    ch = config.CHANNEL_ID()\n    if ch.startswith("@"):\n        return f"https://t.me/{ch[1:]}/{msg[\'message_id\']}"\n    return ""\n\n\ndef notify(text):\n    try:\n        tg.send_message(config.ADMIN_CHAT_ID(), text)\n    except Exception as e:  # noqa: BLE001\n        log.error("Adminga yuborilmadi: %s", e)\n\n\ndef record(history, post, status, msg=None):\n    history.append({\n        "date": now().strftime("%Y-%m-%d"), "time": now().strftime("%H:%M"),\n        "topic": post.get("topic"), "title": post.get("title"),\n        "qc_score": post.get("qc", {}).get("score"), "status": status,\n        "link": post_link(msg) if msg else "",\n    })\n    save_history(history)\n\n\ndef build_with_retry(past, exclude=None, tries=2):\n    last = None\n    for _ in range(tries):\n        try:\n            return build_post(past, exclude)\n        except Exception as e:  # noqa: BLE001\n            last = e\n            log.exception("Post yig\'ishda xato")\n    raise RuntimeError(f"Post tayyorlanmadi: {last}")\n\n\ndef wait_for_regen(pid, offset, deadline, admin):\n    """deadline\'gacha \'Qayta qilish\' bosilishini kutadi."""\n    while (left := (deadline - now()).total_seconds()) > 0:\n        try:\n            ups = tg.get_updates(offset, timeout=int(max(1, min(20, left))))\n        except Exception as e:  # noqa: BLE001\n            log.warning("getUpdates: %s", e)\n            time.sleep(3)\n            continue\n        for u in ups:\n            offset = u["update_id"] + 1\n            cq = u.get("callback_query")\n            if not cq:\n                continue\n            same_chat = str(cq.get("message", {}).get("chat", {}).get("id")) == str(admin)\n            if cq.get("data") == f"regen:{pid}" and same_chat:\n                tg.answer_callback(cq["id"], "Qayta tayyorlanmoqda...")\n                tg.get_updates(offset, timeout=0)  # tasdiqlash\n                return True\n            tg.answer_callback(cq["id"], "Bu post allaqachon eskirgan")\n    return False\n\n\ndef run(mode):\n    history = load_history()\n    today = now().strftime("%Y-%m-%d")\n    if mode == "scheduled" and any(h["date"] == today and h["status"].startswith("published") for h in history):\n        log.info("Bugun post allaqachon chiqqan")\n        return\n\n    admin, channel = config.ADMIN_CHAT_ID(), config.CHANNEL_ID()\n    past = [h.get("title") or h.get("topic") or "" for h in history]\n\n    if mode == "scheduled":\n        hh, mm = map(int, config.S["publish_time"].split(":"))\n        publish_at = now().replace(hour=hh, minute=mm, second=0, microsecond=0)\n        preview_at = publish_at - timedelta(minutes=config.S["preview_minutes"])\n\n    try:\n        post = build_with_retry(past)\n    except Exception as e:  # noqa: BLE001\n        notify(f"❌ Bugungi post tayyorlanmadi.\\n<code>{html.escape(str(e)[:500])}</code>")\n        raise\n\n    if mode == "scheduled":\n        sleep_until(preview_at)\n    else:\n        publish_at = now() + timedelta(minutes=config.S["preview_minutes"])\n\n    # Kechikib qolgan bo\'lsa ham kamida 3 daqiqa ko\'rib chiqish vaqti\n    publish_at = max(publish_at, now() + timedelta(minutes=config.S.get("min_review_minutes", 3)))\n\n    pid = uuid.uuid4().hex[:8]\n    offset = tg.drain_updates()\n    head = f"📝 <b>Bugungi post</b> — {publish_at:%H:%M} da kanalga chiqadi"\n    if mode == "dry":\n        head = "🧪 <b>Sinov posti</b> — kanalga chiqmaydi"\n    tg.send_message(admin, head + ("\\n\\n" + "\\n".join(post["warnings"]) if post["warnings"] else ""))\n    tg.publish(admin, post)\n\n    if mode == "dry":\n        return\n\n    markup = {"inline_keyboard": [[{"text": "🔄 Qayta qilish", "callback_data": f"regen:{pid}"}]]}\n    ctrl = tg.send_message(admin, f"⏰ {publish_at:%H:%M} da chiqadi. Yoqmasa — bosing:", markup=markup)\n\n    if wait_for_regen(pid, offset, publish_at, admin):\n        tg.edit_text(admin, ctrl["message_id"], "♻️ Yangi post tayyorlanmoqda... Tayyor bo\'lishi bilan kanalga chiqadi.")\n        record(history, post, "rejected")\n        past.append(post.get("title") or "")\n        try:\n            new = build_with_retry(past, exclude=[post.get("topic") or "", post.get("title") or ""])\n        except Exception as e:  # noqa: BLE001\n            notify(f"❌ Qayta tayyorlab bo\'lmadi, kanalga hech narsa chiqmadi.\\n<code>{html.escape(str(e)[:400])}</code>")\n            raise\n        msg = tg.publish(channel, new)\n        record(history, new, "published_regen", msg)\n        notify("✅ Yangi post kanalga chiqdi. " + post_link(msg) +\n               ("\\n" + "\\n".join(new["warnings"]) if new["warnings"] else ""))\n    else:\n        msg = tg.publish(channel, post)\n        record(history, post, "published", msg)\n        tg.edit_text(admin, ctrl["message_id"], "✅ Kanalga chiqdi. " + post_link(msg))\n\n\nif __name__ == "__never__":\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--mode", default="scheduled", choices=["scheduled", "now", "dry"])\n    run(ap.parse_args().mode)\n'

def _load():
    for pkg in ("autopost", "autopost.agents"):
        m = types.ModuleType(pkg); m.__path__ = []; sys.modules[pkg] = m
    for name, code in _SRC.items():
        m = types.ModuleType(name)
        m.__file__ = str(Path(__file__).resolve())
        m.__package__ = name.rsplit(".", 1)[0] if name.count(".") > 1 or name.startswith("autopost.agents") else "autopost"
        if name.startswith("autopost.agents."):
            m.__package__ = "autopost.agents"
        sys.modules[name] = m
        parent, _, child = name.rpartition(".")
        exec(compile(code, f"<{name}>", "exec"), m.__dict__)
        setattr(sys.modules[parent], child, m)
    return sys.modules["autopost.main"]


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--mode", default="scheduled", choices=["scheduled", "now", "dry"])
    _load().run(ap.parse_args().mode)
